      "sov.ca": { s: "L’autorité qui donne sa confiance au certificat a son siège en Suisse.", x: "Racine de la chaîne via CCADB (lien SHA-256), domicile du titulaire et de sa maison mère. CH = rempli, EEE = partiel." },
      "sov.dns": { s: "L’annuaire du domaine est exploité par un fournisseur en Suisse.", x: "NS de la zone, IP → AS → pays (Team Cymru). Tous CH = rempli, CH/EEE = partiel." },
      "sov.hosting": { s: "Les serveurs du service se trouvent dans un réseau enregistré en Suisse.", x: "Pays de l’AS de toutes les adresses A/AAAA (Team Cymru). Tous CH = rempli, CH/EEE = partiel." },
      "sov.tld": { s: "L’adresse se termine par .ch ou .swiss, gérés en Suisse.", x: "TLD .ch ou .swiss = rempli." },
      "sec.tls13": { s: "La connexion utilise la version actuelle du chiffrement.", x: "Version négociée par point d’accès. Tous TLS 1.3 = rempli, certains = partiel." },
